-- Heroes of Horror class spell lists.
-- Source: Archivist pp. 82-84; Dread Necromancer p. 87; Corrupt Avenger p. 90; Death Delver p. 94.
-- Existing PHB spell rows are linked by canonical spell name; Heroes of Horror spells are linked by source/name.

-- Archivists begin from the cleric spell list and can add other divine spells under the prayerbook rules.
INSERT OR IGNORE INTO dnd35_spell_class_levels (spell_id,class_id,spell_level)
SELECT scl.spell_id,a.id,scl.spell_level
FROM dnd35_spell_class_levels scl
JOIN dnd35_classes cleric ON cleric.id=scl.class_id AND cleric.slug='cleric' AND cleric.owner_user_id IS NULL
JOIN dnd35_classes a ON a.slug='archivist' AND a.source_id='hoh-3.5' AND a.owner_user_id IS NULL;

