INSERT OR IGNORE INTO dnd35_spell_class_levels (spell_id,class_id,spell_level)
SELECT sp.id,c.id,d.spell_level
FROM desired d
JOIN dnd35_classes c ON c.slug=d.class_slug AND c.source_id='hoh-3.5' AND c.owner_user_id IS NULL
JOIN dnd35_spells sp ON sp.source_id=d.spell_source AND sp.name=d.spell_name AND sp.owner_user_id IS NULL;
